function animate(env,el,p){
    var t=el.text,out="",cs="ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for(var i=0;i<t.length;i++){ var c=t.charAt(i); if(c==" "){out+=c;continue;}
        var r=(AM.simplexNoise(i*9.3, p.seed+Math.floor(env.absTime*p.speed))+1)/2;
        out += r<p.amount ? cs.charAt(Math.floor(r*cs.length)) : c; }
    el.text=out; return el;
}
